class User::Bot::WebhookTest < ActionDispatch::IntegrationTest
  setup do
    @author = users(:david)
    @room = rooms(:hq)
    @bot = User.bot.create!(
      name: "Deploy Bot",
      creator: @author,
      webhook_url: "https://hooks.example.com/deploy?source=campfire"
    )
    @room.memberships.grant_to(@bot)
    clear_enqueued_jobs
    sign_in @author
  end

  test "mentioning a bot enqueues webhook delivery job asynchronously without blocking message creation" do
    assert_enqueued_jobs 1, only: Bots::WebhookDeliveryJob do
      post room_messages_url(@room), params: {
        message: {
          body: "<div>#{mention_attachment_for(@bot)} restart the build please</div>"
        }
      }, as: :turbo_stream
    end

    assert_response :success
  end

  test "delivers exact JSON payload with relative paths, stripped mention text, and full rich-text html" do
    received_headers = nil
    received_payload = nil

    WebMock.stub_request(:post, "https://hooks.example.com/deploy?source=campfire").to_return do |request|
      received_headers = request.headers
      received_payload = JSON.parse(request.body)
      { status: 204 }
    end

    perform_enqueued_jobs only: Bots::WebhookDeliveryJob do
      post room_messages_url(@room), params: {
        message: {
          body: "<div>#{mention_attachment_for(@bot)}&nbsp;<strong>restart</strong> the build please</div>"
        }
      }, as: :turbo_stream
    end

    message = @room.messages.ordered.last
    assert_equal "application/json", received_headers["Content-Type"]
    assert_equal(
      {
        "event" => "mention",
        "author" => {
          "id" => @author.id,
          "name" => @author.name
        },
        "room" => {
          "id" => @room.id,
          "name" => @room.name,
          "reply_to" => "/rooms/#{@room.id}/#{@bot.bot_key}/messages"
        },
        "message" => {
          "id" => message.id,
          "body" => {
            "text" => "restart the build please",
            "html" => message.body.body.to_html
          },
          "link" => "/rooms/#{@room.id}/@#{message.id}"
        }
      },
      received_payload
    )

    assert_match(/\A<div>.*<strong>restart<\/strong> the build please<\/div>\z/m, received_payload.dig("message", "body", "html"))

    # Deep link opens the room with the message loaded
    get received_payload.dig("message", "link")
    assert_response :ok
    assert_select "##{dom_id(message)}"

    # Out-of-band reply_to lets the bot post asynchronously
    assert_difference -> { @room.messages.count }, +1 do
      post received_payload.dig("room", "reply_to"),
        params: +"Build #42 finished!",
        headers: { "Content-Type" => "text/plain" }
    end
    assert_response :created
    assert_equal @bot, @room.messages.ordered.last.creator
    assert_equal "Build #42 finished!", @room.messages.ordered.last.plain_text_body
  end

  test "200 text/plain response posts escaped plain text with line breaks as the bot's message and broadcasts it" do
    WebMock.stub_request(:post, "https://hooks.example.com/deploy?source=campfire").to_return(
      status: 200,
      headers: { "Content-Type" => "text/plain; charset=utf-8" },
      body: "Restarting <main> & deploying ✅\nETA: 2m"
    )

    assert_difference -> { @room.messages.count }, +2 do
      perform_enqueued_jobs only: Bots::WebhookDeliveryJob do
        post room_messages_url(@room), params: {
          message: {
            body: "<div>#{mention_attachment_for(@bot)} deploy</div>"
          }
        }, as: :turbo_stream
      end
    end

    user_message, bot_reply = @room.messages.ordered.last(2)
    assert_equal @author, user_message.creator
    assert_equal @bot, bot_reply.creator
    assert_operator bot_reply.created_at.to_fs(:epoch), :>, user_message.created_at.to_fs(:epoch)
    assert_equal "Restarting <main> & deploying ✅\nETA: 2m", bot_reply.plain_text_body

    assert_rendered_turbo_stream_broadcast @room, :messages, action: "append", target: [ @room, :messages ] do
      assert_select ".message__author strong", text: "Deploy Bot"
      assert_select ".message__body", text: /Restarting <main> & deploying ✅/
    end
  end

  test "200 text/html response posts sanitized rich HTML as the bot's message and broadcasts it" do
    WebMock.stub_request(:post, "https://hooks.example.com/deploy?source=campfire").to_return(
      status: 200,
      headers: { "Content-Type" => "TEXT/HTML; charset=UTF-8" },
      body: "<div><strong>Build #42</strong> is <em>live</em>! <a href=\"https://ci.example.com/42\">Logs</a><script>alert(1)</script></div>"
    )

    assert_difference -> { @room.messages.count }, +2 do
      perform_enqueued_jobs only: Bots::WebhookDeliveryJob do
        post room_messages_url(@room), params: {
          message: {
            body: "<div>#{mention_attachment_for(@bot)} status</div>"
          }
        }, as: :turbo_stream
      end
    end

    bot_reply = @room.messages.ordered.last
    assert_equal @bot, bot_reply.creator
    assert_equal "Build #42 is live! Logs", bot_reply.plain_text_body

    get room_url(@room)
    assert_response :ok
    assert_select "##{dom_id(bot_reply)}" do
      assert_select "strong", text: "Build #42"
      assert_select "em", text: "live"
      assert_select "a[href='https://ci.example.com/42']", text: "Logs"
      assert_select "script", count: 0
    end
  end

  test "204 response posts no message" do
    stub = WebMock.stub_request(:post, "https://hooks.example.com/deploy?source=campfire").to_return(status: 204)

    assert_difference -> { @room.messages.count }, +1 do
      perform_enqueued_jobs only: Bots::WebhookDeliveryJob do
        post room_messages_url(@room), params: {
          message: {
            body: "<div>#{mention_attachment_for(@bot)} quiet</div>"
          }
        }, as: :turbo_stream
      end
    end

    assert_requested stub, times: 1
    assert_equal @author, @room.messages.ordered.last.creator
  end

  test "ignores 200 with unsupported content-type, blank 200 bodies, 500 errors, and network timeouts" do
    [
      { status: 200, headers: { "Content-Type" => "application/json" }, body: '{"ok":true}' },
      { status: 200, headers: { "Content-Type" => "text/plain" }, body: "   \n  " },
      { status: 200, headers: { "Content-Type" => "text/html" }, body: "<div>   </div>" },
      { status: 500, headers: { "Content-Type" => "text/html" }, body: "<h1>Internal Server Error</h1>" }
    ].each do |mock_response|
      WebMock.stub_request(:post, "https://hooks.example.com/deploy?source=campfire").to_return(**mock_response)

      assert_difference -> { @room.messages.count }, +1 do
        perform_enqueued_jobs only: Bots::WebhookDeliveryJob do
          post room_messages_url(@room), params: {
            message: {
              body: "<div>#{mention_attachment_for(@bot)} ping</div>"
            }
          }, as: :turbo_stream
        end
      end
    end

    WebMock.stub_request(:post, "https://hooks.example.com/deploy?source=campfire").to_timeout

    assert_difference -> { @room.messages.count }, +1 do
      perform_enqueued_jobs only: Bots::WebhookDeliveryJob do
        post room_messages_url(@room), params: {
          message: {
            body: "<div>#{mention_attachment_for(@bot)} timeout</div>"
          }
        }, as: :turbo_stream
      end
    end
  end

  test "strips only the receiving bot's own mention when multiple bots and users are mentioned" do
    alert_bot = User.bot.create!(
      name: "Alert Bot",
      creator: @author,
      webhook_url: "https://hooks.example.com/alert"
    )
    @room.memberships.grant_to(alert_bot)
    clear_enqueued_jobs

    deploy_payload = nil
    alert_payload = nil

    WebMock.stub_request(:post, "https://hooks.example.com/deploy?source=campfire").to_return do |req|
      deploy_payload = JSON.parse(req.body)
      { status: 204 }
    end
    WebMock.stub_request(:post, "https://hooks.example.com/alert").to_return do |req|
      alert_payload = JSON.parse(req.body)
      { status: 204 }
    end

    perform_enqueued_jobs only: Bots::WebhookDeliveryJob do
      post room_messages_url(@room), params: {
        message: {
          body: "<div>#{mention_attachment_for(@bot)} notify #{mention_attachment_for(alert_bot)} and #{mention_attachment_for(:kevin)}</div>"
        }
      }, as: :turbo_stream
    end

    assert_equal "notify @Alert Bot and @Kevin", deploy_payload.dig("message", "body", "text")
    assert_equal "/rooms/#{@room.id}/#{@bot.bot_key}/messages", deploy_payload.dig("room", "reply_to")

    assert_equal "@Deploy Bot notify and @Kevin", alert_payload.dig("message", "body", "text")
    assert_equal "/rooms/#{@room.id}/#{alert_bot.bot_key}/messages", alert_payload.dig("room", "reply_to")
  end

  test "does not trigger webhook for bot without webhook_url or bot not in closed room" do
    no_hook_bot = User.bot.create!(name: "Silent Bot", creator: @author)
    @room.memberships.grant_to(no_hook_bot)
    closed_room = rooms(:designers)

    assert_no_enqueued_jobs only: Bots::WebhookDeliveryJob do
      post room_messages_url(@room), params: {
        message: { body: "<div>#{mention_attachment_for(no_hook_bot)} hello</div>" }
      }, as: :turbo_stream

      post room_messages_url(closed_room), params: {
        message: { body: "<div>#{mention_attachment_for(@bot)} secret</div>" }
      }, as: :turbo_stream
    end
